def load_prompt(prompt_rel: str) -> tuple[str, str]:
    """Return (antes, prompt) from ai-prompts file."""
    import re
    path = PROMPTS / prompt_rel
    if not path.exists():
        return "", f"*(arquivo não encontrado: {prompt_rel})*"
    text = path.read_text(encoding="utf-8")
    antes, prompt = "", ""
    if "## Antes de colar" in text:
        parts = text.split("## Antes de colar", 1)[1]
        if "## Prompt" in parts:
            antes, rest = parts.split("## Prompt", 1)
            antes = antes.strip()
            m = re.search(r"```\n(.*?)```", rest, re.DOTALL)
            if m:
                prompt = m.group(1).strip()
    return antes, prompt
